package com.example.leetcodetrainer.curriculum.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="learning_session") public class LearningSession { @Id private UUID id; @Column(name="problem_id",nullable=false) private UUID problemId; @Enumerated(EnumType.STRING) private LearningMode suggestedMode,selectedMode; @Enumerated(EnumType.STRING) private ProblemExposureState priorExposureSnapshot; @Enumerated(EnumType.STRING) private LearningSessionStatus status; private Long timeBoxSeconds; @Column(name="legacy_attempt_id") private UUID legacyAttemptId; private String creationReason; private Instant startedAt,completedAt,createdAt,updatedAt; protected LearningSession(){} public UUID getProblemId(){return problemId;} public LearningMode getSuggestedMode(){return suggestedMode;} public LearningMode getSelectedMode(){return selectedMode;} public ProblemExposureState getPriorExposureSnapshot(){return priorExposureSnapshot;} public LearningSessionStatus getStatus(){return status;} public UUID getLegacyAttemptId(){return legacyAttemptId;} }
